import { Bucket, defineConfig } from 'stacktape';

export default defineConfig(() => {
  const myBucket = new Bucket({
    lifecycleRules: [
      {
        type: 'abort-incomplete-multipart-upload',
        properties: {
          // [!code focus-start]
          daysAfterInitiation: 7
          // [!code focus-end]
        }
      }
    ]
  });
  return { resources: { myBucket } };
});

