  metric: "ActiveConnectionCount" | "AnomalousHostCount" | "ClientTLSNegotiationErrorCount" | "ConsumedLCUs" | "DesyncMitigationMode_NonCompliant_Request_Count" | "DroppedInvalidHeaderRequestCount" | "ELBAuthError" | "ELBAuthFailure" | "ELBAuthLatency" | "ELBAuthRefreshTokenSuccess" | "ELBAuthSuccess" | "ELBAuthUserClaimsSizeExceeded" | "ForwardedInvalidHeaderRequestCount" | "GrpcRequestCount" | "HTTPCode_ELB_3XX_Count" | "HTTPCode_ELB_4XX_Count" | "HTTPCode_ELB_500_Count" | "HTTPCode_ELB_502_Count" | "HTTPCode_ELB_503_Count" | "HTTPCode_ELB_504_Count" | "HTTPCode_ELB_5XX_Count" | "HTTPCode_Target_2XX_Count" | "HTTPCode_Target_3XX_Count" | "HTTPCode_Target_4XX_Count" | "HTTPCode_Target_5XX_Count" | "HTTP_Fixed_Response_Count" | "HTTP_Redirect_Count" | "HTTP_Redirect_Url_Limit_Exceeded_Count" | "HealthyHostCount" | "HealthyStateDNS" | "HealthyStateRouting" | "IPv6ProcessedBytes" | "IPv6RequestCount" | "LambdaInternalError" | "LambdaTargetProcessedBytes" | "LambdaUserError" | "MitigatedHostCount" | "NewConnectionCount" | "NonStickyRequestCount" | "ProcessedBytes" | "RejectedConnectionCount" | "RequestCount" | "RequestCountPerTarget" | "RuleEvaluations" | "TargetConnectionErrorCount" | "TargetResponseTime" | "TargetTLSNegotiationErrorCount" | "UnHealthyHostCount" | "UnhealthyRoutingRequestCount" | "UnhealthyStateDNS" | "UnhealthyStateRouting";
  /** The threshold that triggers the alarm. */
  threshold: number;
  /** How to compare the metric value against the threshold. */
  comparisonOperator?: "GreaterThanOrEqualToThreshold" | "GreaterThanThreshold" | "LessThanOrEqualToThreshold" | "LessThanThreshold";
  /** How to aggregate metric values within each period: `avg`, `sum`, `min`, `max`, `p90`, `p95`, `p99`. */
  statistic?: "avg" | "max" | "min" | "p90" | "p95" | "p99" | "sum";
};
