type BucketCorsRule = {
  /** Allowed request headers. */
  allowedHeaders?: Array<string>;
  /** Allowed HTTP methods. */
  allowedMethods?: Array<"*" | "DELETE" | "GET" | "HEAD" | "PATCH" | "POST" | "PUT">;
