LambdaAlarm.typeDeclaration:
import type { AlarmEvaluation, DiscordIntegration, EmailIntegration, LambdaDurationTrigger, LambdaErrorRateTrigger, MsTeamsIntegration, SlackIntegration, WebhookIntegration } from 'stacktape';

// [!code focus-start]
type LambdaAlarm = {
  trigger: LambdaAlarmTrigger;
  /** Custom alarm description used in notification messages and the AWS console. */
  description?: string;
  /** How long and how often to evaluate the metric before triggering. */
  evaluation?: AlarmEvaluation;
  /** Whether alarm state changes should appear in monitoring history. */
  includeInHistory?: boolean;
  /** Where to send notifications when the alarm fires — Slack, MS Teams, or email. */
  notificationTargets?: Array<LambdaAlarmNotificationTargets>;
};

/** Union choices used by the properties above. */
type LambdaAlarmTrigger =
  | LambdaErrorRateTrigger
  | LambdaDurationTrigger;

type LambdaAlarmNotificationTargets =
  | SlackIntegration
  | MsTeamsIntegration
  | EmailIntegration
  | DiscordIntegration
  | WebhookIntegration;
// [!code focus-end]

