```yaml
resources:
  notificationsService:
    type: private-service
    properties:
      packaging:
        type: stacktape-image-buildpack
        properties:
          entryfilePath: src/notifications.ts
      port: 3000
      resources:
        cpu: 1
        memory: 1024
      loadBalancing:
        type: service-connect
```

