  s3EventType: "s3:ObjectCreated:*" | "s3:ObjectCreated:CompleteMultipartUpload" | "s3:ObjectCreated:Copy" | "s3:ObjectCreated:Post" | "s3:ObjectCreated:Put" | "s3:ObjectRemoved:*" | "s3:ObjectRemoved:Delete" | "s3:ObjectRemoved:DeleteMarkerCreated" | "s3:ObjectRestore:*" | "s3:ObjectRestore:Completed" | "s3:ObjectRestore:Post" | "s3:ReducedRedundancyLostObject" | "s3:Replication:*" | "s3:Replication:OperationFailedReplication" | "s3:Replication:OperationMissedThreshold" | "s3:Replication:OperationNotTracked" | "s3:Replication:OperationReplicatedAfterThreshold";
  /** A filter to apply to objects, so the function is only triggered for relevant objects. */
  filterRule?: S3FilterRule;
};
// [!code focus-end]

ScheduleIntegration.typeDeclaration:
import type { ScheduleIntegrationProps } from 'stacktape';

// [!code focus-start]
type ScheduleIntegration = {
  properties: ScheduleIntegrationProps;
};
// [!code focus-end]

properties.longDescription:
If you need to customize the payload based on the event, use `inputTransformer` instead.
You can only use one of `input`, `inputPath`, or `inputTransformer`.

**Example (YAML):**

```yaml
resources:
  reportFunction:
    type: function
    properties:
      packaging:
        type: stacktape-lambda-buildpack
        properties:
          entryfilePath: src/report.ts
      events:
        - type: schedule
          properties:
            scheduleRate: rate(1 hour)
            input:
              source: my-scheduled-event
```

**Example (TypeScript):**

```ts
import { LambdaFunction, StacktapeLambdaBuildpackPackaging, defineConfig } from 'stacktape';

export default defineConfig(() => {
  const reportFunction = new LambdaFunction({
    packaging: new StacktapeLambdaBuildpackPackaging({ entryfilePath: 'src/report.ts' }),
    events: [
      {
        type: 'schedule',
        properties: {
          scheduleRate: 'rate(1 hour)',
          input: { source: 'my-scheduled-event' }
        }
      }
    ]
  });
  return { resources: { reportFunction } };
});
```

