            - sqs:SendMessage
          Condition:
            ArnEquals:
              aws:SourceArn: arn:aws:sns:eu-west-1:123456789012:order-events-topic
  topicBoundWorker:
    type: function
    properties:
      packaging:
        type: stacktape-lambda-buildpack
        properties:
          entryfilePath: src/topic-bound-worker.ts
      events:
        - type: sqs
          properties:
            sqsQueueName: topicBoundQueue
