StateMachineDefinition.typeDeclaration:
// [!code focus-start]
type StateMachineDefinition = {
  /** The name of the state to start the execution at. */
  StartAt: string;
  /** An object containing the states of the state machine. */
  States: unknown;
  /** A human-readable description of the state machine. */
  Comment?: string;
  /** The maximum time, in seconds, that a state machine can run. */
  TimeoutSeconds?: number;
  /** The version of the Amazon States Language. */
  Version?: string;
};
// [!code focus-end]

StateMachineMap.typeDeclaration:
import type { StpStateMachine } from 'stacktape';

// [!code focus-start]
type StateMachineMap = {
  Iterator: StpStateMachine;
  Type: string;
  Catch?: Array<unknown>;
  Comment?: string;
  End?: boolean;
  InputPath?: string;
  ItemsPath?: string;
  MaxConcurrency?: number;
  Next?: string;
  OutputPath?: string;
  Parameters?: unknown;
  ResultPath?: string;
  Retry?: Array<unknown>;
};
// [!code focus-end]

